import re, html
h = open('/workspace/fetched/daily_climate_obs.html', encoding='utf-8').read()
# find resource blocks: title then link
for m in re.finditer(r'<a[^>]*href="(/data/en/dataset/5f963c2d-d4ed-5a79-8a31-c9c582ca5098/resource/[0-9a-f-]+)"[^>]*>(.*?)</a>', h, re.S):
    print(html.unescape(re.sub(r'<[^>]+>','',m.group(2))).strip()[:60], '->', m.group(1))
# also look for data download links (datastore / .csv)
for m in re.finditer(r'href="([^"]*(?:\.csv|datastore|api)[^"]*)"', h):
    print('DL:', m.group(1))
EOF"}

