import re, html as H
t = open('/workspace/fetched/yow_yesterday.html', encoding='utf-8').read()
# find station id references
for m in re.finditer(r'(?:station|stn|STN)[^0-9]{0,20}(\d{4,5})', t):
    print('station ref:', m.group(1))
# find links to historical data with params
for m in re.finditer(r'href="([^"]*(?:historic|climate|data)[^"]*)"', t):
    print('link:', m.group(1)[:150])
# look for snow data in the page
for m in re.finditer(r'[Ss]now[^<]{0,80}', t):
    s = H.unescape(m.group(0))
    if any(c.isdigit() for c in s):
        print('snow:', s[:100])
EOF"}

