{"description":"Check data quality for YOW 2025 Nov-Dec","command":"python3 - <<'EOF'
import csv
from datetime import date

with open('/workspace/fetched/yow_2025.csv', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    rows = list(reader)

# Check all Nov-Dec 2025 rows
print("All Nov-Dec 2025 records:")
for row in rows:
    try:
        d = date(int(row['LOCAL_YEAR']), int(row['LOCAL_MONTH']), int(row['LOCAL_DAY']))
    except (ValueError, KeyError):
        continue
    if date(2025, 11, 1) <= d <= date(2025, 12, 31):
        print(f"  {d}: SNOW='{row.get('TOTAL_SNOW','')}' RAIN='{row.get('TOTAL_RAIN','')}' PRECIP='{row.get('TOTAL_PRECIPITATION','')}'")

# Also check if there's ANY snow in the entire 2025 file
print("\nAny snowfall in 2025?")
snow_days = []
for row in rows:
    s = row.get('TOTAL_SNOW', '').strip()
    if s and s != '':
        try:
            snow_days.append((row['LOCAL_DATE'], float(s)))
        except ValueError:
            pass

print(f"Total days with snow in 2025: {len(snow_days)}")
if snow_days:
    snow_days.sort()
    print("First 5:", snow_days[:5])
    print("Last 5:", snow_days[-5:])
    print(f"Max single day: {max(s for _, s in snow_days):.1f} cm")
    print(f"Total 2025 snowfall: {sum(s for _, s in snow_days):.1f} cm")
EOF"}

